function calculateHomeGymBreakeven() {
  const gymMonthly = parseFloat(document.getElementById('gymMonthlyFee').value) || 0;
  const travelMonthly = parseFloat(document.getElementById('travelCostMonthly').value) || 0;
  const homeGymCost = parseFloat(document.getElementById('homeGymCost').value) || 0;
  const tripMinutes = parseFloat(document.getElementById('roundTripMinutes').value) || 0;
  const monthlyWorkouts = parseFloat(document.getElementById('monthlyWorkouts').value) || 0;

  const totalMonthlyGymCost = gymMonthly + travelMonthly;
  const resultEl = document.getElementById('calcResult');

  if (totalMonthlyGymCost <= 0) {
    resultEl.innerHTML = '<div class="result-headline">ジム代金を入力してください</div>';
    return;
  }

  const breakevenMonths = (homeGymCost / totalMonthlyGymCost).toFixed(1);
  const yearlyGymSavings = (totalMonthlyGymCost * 12) - (homeGymCost);
  const threeYearSavings = (totalMonthlyGymCost * 36) - homeGymCost;
  const annualSavedHours = Math.round((tripMinutes * monthlyWorkouts * 12) / 60);

  let conclusionText = '';
  if (parseFloat(breakevenMonths) <= 12) {
    conclusionText = '約 ' + breakevenMonths + ' ヶ月（1年未満）で元が取れます！';
  } else {
    conclusionText = '約 ' + breakevenMonths + ' ヶ月で元が取れます！';
  }

  resultEl.innerHTML = `
    <div class="result-headline">結論：<strong>${conclusionText}</strong></div>
    <div class="metrics-row">
      <div class="metric-card">
        <span>損益分岐点</span>
        <strong>${breakevenMonths} ヶ月</strong>
        <small>初期費用を回収できる期間</small>
      </div>
      <div class="metric-card">
        <span>3年間の純節約額</span>
        <strong>${threeYearSavings.toLocaleString()} 円</strong>
        <small>ジム代・交通費から器具代を引いた浮くお金</small>
      </div>
      <div class="metric-card">
        <span>年間の節約移動時間</span>
        <strong>${annualSavedHours} 時間</strong>
        <small>移動・準備に使わずに済む自由時間</small>
      </div>
    </div>
  `;
}
document.addEventListener('DOMContentLoaded', calculateHomeGymBreakeven);
